import { createServer } from "node:http";
import { createHash, randomBytes } from "node:crypto";

const scopes = new Map(); // sha256(capability) -> scope; the capability itself is never stored
const sha = (s) => createHash("sha256").update(s).digest("hex");
const audit = (scope, route, decision, reason = "") =>
  console.log(JSON.stringify({ run: scope?.runId ?? "-", route, decision, reason }));
const safeName = (name) => name.replace(/[^a-zA-Z0-9._-]/g, "_");

const routes = {
  "POST /v1/slack/post": (body, s) =>
    body.thread_ts === s.slackThreadTs ? [200, { posted: true }] : [403, { error: `only thread ${s.slackThreadTs}` }],
  "POST /v1/jira/comment": (body, s) =>
    body.issue_key === s.jiraKey ? [200, { commented: s.jiraKey }] : [403, { error: `only ${s.jiraKey} can be commented on` }],
  "POST /v1/artifacts/url": (body, s) => [200, { key: `runs/${s.runId}/${safeName(body.name)}` }],
};

createServer(async (req, res) => {
  let raw = "";
  for await (const chunk of req) raw += chunk;
  const body = raw ? JSON.parse(raw) : {};
  const send = (status, obj) => res.writeHead(status, { "content-type": "application/json" }).end(JSON.stringify(obj) + "\n");

  if (req.method === "POST" && req.url === "/internal/runs") { // the orchestrator opens a scope
    const capability = randomBytes(32).toString("hex");
    scopes.set(sha(capability), body);
    return send(201, { capability });
  }
  if (req.method === "DELETE" && req.url.startsWith("/internal/runs/")) { // the orchestrator closes it
    const runId = decodeURIComponent(req.url.split("/").pop());
    for (const [digest, s] of scopes) if (s.runId === runId) scopes.delete(digest);
    return send(200, { revoked: runId });
  }
  const scope = scopes.get(sha((req.headers.authorization ?? "").replace("Bearer ", "")));
  const route = `${req.method} ${req.url}`;
  if (!scope) { audit(null, route, "deny", "no such capability"); return send(401, { error: "unauthorized" }); }
  const handler = routes[route];
  if (!handler) { audit(scope, route, "deny", "not on the allow-list"); return send(404, { error: "no such route" }); }
  const [status, reply] = handler(body, scope);
  audit(scope, route, status === 200 ? "allow" : "deny", reply.error ?? "");
  send(status, reply);
}).listen(8080, () => console.log("broker listening on 8080"));
EOF

