const found = scopes.get(sha((req.headers.authorization ?? "").replace("Bearer ", "")));
const expired = found?.expiresAt && new Date(found.expiresAt) <= new Date();
const scope = expired ? undefined : found;
const route = `${req.method} ${req.url}`;
if (!scope) { audit(null, route, "deny", expired ? "scope expired" : "no such capability"); return send(401, { error: "unauthorized" }); }

// open a scope that lives 30 seconds:
// curl -s -X POST localhost:8080/internal/runs -d "{\"runId\":\"run-8\",\"slackThreadTs\":\"1760.42\",\"expiresAt\":\"$(date -u -v+30S +%FT%TZ)\"}"
// (on Linux: date -u -d '+30 seconds' +%FT%TZ)
